package com.cowave.search.dictionary.service

import co.elastic.clients.elasticsearch._types.mapping.DynamicMapping
import co.elastic.clients.transport.rest5_client.low_level.Request
import com.cowave.search.common.elasticsearch.ElasticsearchClientFactory
import com.cowave.search.dictionary.dto.AllTypesCountResponse
import com.cowave.search.dictionary.dto.AllTypesLastModifiedResponse
import com.cowave.search.dictionary.dto.CompileResult
import com.cowave.search.dictionary.dto.CursorPagedResponse
import com.cowave.search.dictionary.dto.DictApplyHistory
import com.cowave.search.dictionary.dto.DictionarySetting
import com.cowave.search.dictionary.dto.SearchColumn
import com.cowave.search.dictionary.dto.SortType
import com.cowave.search.dictionary.dto.TypeCountResponse
import com.cowave.search.dictionary.dto.TypeLastModifiedResponse
import com.cowave.search.dictionary.infrastructure.DictionaryRepositoryImpl.Companion.DICT_APPLY_INDEX
import com.cowave.search.dictionary.model.Dictionary
import com.cowave.search.dictionary.model.Type
import com.cowave.search.utils.DictionaryBinaryCompile
import org.slf4j.LoggerFactory
import org.springframework.stereotype.Service
import org.springframework.web.multipart.MultipartFile
import java.time.Instant

@Service
class DictionaryService(
    val dictionaryRepository: DictionaryRepository,
    val dictionaryBinaryCompile: DictionaryBinaryCompile,
    private val clientFactory: ElasticsearchClientFactory,
) {
    private val logger = LoggerFactory.getLogger(DictionaryService::class.java)

    fun search(
        clusterId: String,
        type: Type,
        size: Int,
        searchColumn: SearchColumn = SearchColumn.ALL,
        word: String? = null,
        isMatch: Boolean = false,
        cursor: String? = null,
        sortType: SortType = SortType.UPDATED,
    ): CursorPagedResponse<Dictionary> {
        val searchAfterList = cursor?.split(CURSOR_DELIMITER)
        val result =
            dictionaryRepository.search(
                clusterId = clusterId,
                type = type,
                size = size,
                searchColumn = searchColumn,
                value = word,
                isMatch = isMatch,
                searchAfter = searchAfterList,
                sortType = sortType,
            )

        return CursorPagedResponse(
            items = result.items,
            total = result.total,
            cursor = result.searchAfter?.joinToString(CURSOR_DELIMITER),
            hasNext = result.hasNext,
        )
    }

    fun create(
        clusterId: String,
        keyword: String?,
        type: Type,
        value: String?,
    ) {
        dictionaryRepository.insert(clusterId, keyword, type, value)
    }

    fun update(
        clusterId: String,
        id: String,
        keyword: String,
        type: Type,
        value: String?,
    ) {
        dictionaryRepository.update(clusterId, id, keyword, type, value)
    }

    fun delete(
        clusterId: String,
        id: String,
    ) {
        dictionaryRepository.delete(clusterId, id)
    }

    fun countByType(
        clusterId: String,
        type: Type,
    ): Long = dictionaryRepository.countByType(clusterId, type)

    fun compile(
        clusterId: String,
        type: Type,
    ): CompileResult {
        val result = compileWithoutReload(clusterId, type)
        reloadDictionary(clusterId)
        return result
    }

    fun compileAll(clusterId: String): List<CompileResult> {
        val results: List<CompileResult> = Type.entries.map { compileWithoutReload(clusterId, it) }
        reloadDictionary(clusterId)
        return results
    }

    private fun compileWithoutReload(
        clusterId: String,
        type: Type,
    ): CompileResult {
        val dictionaries = dictionaryRepository.findAllByType(clusterId, type)
        val pairs = dictionaries.map { it.keyword to it.value }
        val outputFile = dictionaryBinaryCompile.compileToConfiguredPath(pairs, type)

        return CompileResult(
            type = type,
            count = dictionaries.size,
            filePath = outputFile.absolutePath,
            fileSize = outputFile.length(),
        )
    }

    private fun reloadDictionary(clusterId: String) {
        logger.info("Reloading dictionary in Elasticsearch cluster: {}", clusterId)
        val restClient = clientFactory.getLowLevelClient(clusterId)
        val request = Request("POST", "/_analysis-product-name/reload-dict")
        val response = restClient.performRequest(request)
        val statusCode = response.statusCode
        if (statusCode !in 200..299) {
            throw RuntimeException("Failed to reload dictionary: HTTP $statusCode")
        }
        logger.info("Dictionary reload completed successfully for cluster: {}", clusterId)
    }

    fun getLastModifiedByType(
        clusterId: String,
        type: Type,
    ): TypeLastModifiedResponse {
        val (lastModified, count) = dictionaryRepository.findLastModifiedByType(clusterId, type)
        return TypeLastModifiedResponse(
            type = type,
            lastModified = lastModified,
            count = count,
        )
    }

    fun getAllTypesLastModified(clusterId: String): AllTypesLastModifiedResponse {
        val allTypesData = dictionaryRepository.findLastModifiedForAllTypes(clusterId)
        val items =
            Type.entries.map { type ->
                val (lastModified, count) = allTypesData[type] ?: Pair(null, 0L)
                TypeLastModifiedResponse(
                    type = type,
                    lastModified = lastModified,
                    count = count,
                )
            }
        return AllTypesLastModifiedResponse(items)
    }

    fun getAllTypesCounts(clusterId: String): AllTypesCountResponse {
        val allTypesCounts = dictionaryRepository.countAllTypes(clusterId)
        val items =
            Type.entries.map { type ->
                TypeCountResponse(
                    type = type,
                    count = allTypesCounts[type] ?: 0L,
                )
            }
        val totalCount = items.sumOf { it.count }
        return AllTypesCountResponse(items, totalCount)
    }

    // ── 파일 업로드 일괄 등록 ─────────────────────────────────────────────

    fun fileUpload(
        clusterId: String,
        type: Type,
        file: MultipartFile,
    ): Int {
        val entries =
            file.inputStream.bufferedReader().useLines { lines ->
                lines
                    .filter { it.isNotBlank() }
                    .map { line ->
                        val parts = line.split("\t", limit = 2)
                        val keyword = parts[0].trim().takeIf { it.isNotEmpty() }
                        val value = parts.getOrNull(1)?.trim()
                        Dictionary.of(
                            keyword = keyword,
                            type = type,
                            value = value,
                            createdTime = Instant.now(),
                            updatedTime = Instant.now(),
                        )
                    }.toList()
            }
        dictionaryRepository.bulkInsert(clusterId, entries)
        return entries.size
    }

    // ── 전체 다운로드 ─────────────────────────────────────────────────────

    fun downloadAll(
        clusterId: String,
        type: Type,
    ): String {
        val dictionaries = dictionaryRepository.findAllByType(clusterId, type)
        return dictionaries.joinToString("\n") { dict ->
            if (dict.value != null) "${dict.keyword}\t${dict.value}" else dict.keyword ?: ""
        }
    }

    // ── 전체 삭제 ─────────────────────────────────────────────────────────

    fun resetDict(
        clusterId: String,
        type: Type,
    ) {
        dictionaryRepository.deleteAllByType(clusterId, type)
    }

    // ── 사전 설정 조회 ────────────────────────────────────────────────────

    fun getSettings(clusterId: String): List<DictionarySetting> {
        val esClient = clientFactory.getClient(clusterId)
        return runCatching {
            val indexExists =
                esClient
                    .indices()
                    .exists { it.index("dsearch-dict") }
                    .value()
            if (!indexExists) {
                ensureDictIndexExists(clusterId)
            }
            val mapping = esClient.indices().getMapping { it.index("dsearch-dict") }
            Type.entries.map { type ->
                DictionarySetting(
                    type = type,
                    indexName = "dsearch-dict",
                    mappingExists = mapping.mappings().containsKey("dsearch-dict"),
                )
            }
        }.getOrElse {
            logger.warn("사전 설정 조회 실패 [{}]: {}", clusterId, it.message)
            Type.entries.map { type -> DictionarySetting(type = type, indexName = "dsearch-dict", mappingExists = false) }
        }
    }

    private fun ensureDictIndexExists(clusterId: String) {
        val esClient = clientFactory.getClient(clusterId)
        esClient.indices().create { req ->
            req.index("dsearch-dict").mappings { m ->
                m
                    .dynamic(DynamicMapping.True)
                    .properties("type") { p -> p.keyword { it } }
                    .properties("keyword") { p -> p.keyword { k -> k.fields("text") { f -> f.text { it } } } }
                    .properties("value") { p -> p.text { t -> t.fields("raw") { f -> f.keyword { it } } } }
                    .properties("createdTime") { p -> p.date { it } }
                    .properties("updatedTime") { p -> p.date { it } }
            }
        }
        logger.info("dsearch-dict 인덱스 생성: {}", clusterId)
    }

    // ── 배포 이력 조회 ────────────────────────────────────────────────────

    fun getApplyHistory(
        clusterId: String,
        size: Int,
    ): List<DictApplyHistory> {
        val esClient = clientFactory.getClient(clusterId)
        return runCatching {
            val response =
                esClient.search(
                    { s ->
                        s
                            .index(DICT_APPLY_INDEX)
                            .size(size)
                            .sort { so ->
                                so.field { f -> f.field("applyTime").order(co.elastic.clients.elasticsearch._types.SortOrder.Desc) }
                            }
                    },
                    DictApplyHistory::class.java,
                )
            response.hits().hits().mapNotNull { it.source() }
        }.getOrElse {
            logger.warn("배포 이력 조회 실패 [{}]: {}", clusterId, it.message)
            emptyList()
        }
    }

    fun saveApplyHistory(
        clusterId: String,
        history: DictApplyHistory,
    ) {
        val esClient = clientFactory.getClient(clusterId)
        runCatching {
            esClient.index { it.index(DICT_APPLY_INDEX).document(history) }
        }.onFailure { e ->
            logger.warn("배포 이력 저장 실패 [{}]: {}", clusterId, e.message)
        }
    }

    companion object {
        private const val CURSOR_DELIMITER = "|"
    }
}

package com.cowave.search.common.elasticsearch

import co.elastic.clients.elasticsearch.ElasticsearchClient
import co.elastic.clients.json.jackson.JacksonJsonpMapper
import co.elastic.clients.transport.rest5_client.Rest5ClientTransport
import co.elastic.clients.transport.rest5_client.low_level.Rest5Client
import com.fasterxml.jackson.databind.ObjectMapper
import com.fasterxml.jackson.databind.SerializationFeature
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule
import com.fasterxml.jackson.module.kotlin.kotlinModule
import jakarta.annotation.PreDestroy
import org.apache.hc.core5.http.Header
import org.apache.hc.core5.http.HttpHost
import org.apache.hc.core5.http.message.BasicHeader
import org.slf4j.LoggerFactory
import org.springframework.stereotype.Component
import java.util.Base64
import java.util.concurrent.ConcurrentHashMap

/**
 * 멀티 클러스터 Elasticsearch 클라이언트 팩토리.
 *
 * - ConcurrentHashMap 기반 클라이언트 캐시
 * - 클러스터 등록/삭제 시 캐시 갱신
 * - Basic 인증 및 ApiKey 인증 지원
 */
@Component
class ElasticsearchClientFactory {
    private val logger = LoggerFactory.getLogger(ElasticsearchClientFactory::class.java)

    private val clientCache = ConcurrentHashMap<String, CachedClusterClient>()

    private val jsonpMapper by lazy {
        val objectMapper =
            ObjectMapper()
                .registerModule(kotlinModule())
                .registerModule(JavaTimeModule())
                .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS)
        JacksonJsonpMapper(objectMapper)
    }

    fun getClient(clusterId: String): ElasticsearchClient =
        clientCache[clusterId]?.esClient
            ?: throw IllegalArgumentException("등록되지 않은 클러스터입니다: $clusterId")

    fun getLowLevelClient(clusterId: String): Rest5Client =
        clientCache[clusterId]?.restClient
            ?: throw IllegalArgumentException("등록되지 않은 클러스터입니다: $clusterId")

    fun registerCluster(info: ClusterConnectionInfo) {
        val cached = buildCachedClient(info)
        clientCache[info.id] = cached
        logger.info("ES 클러스터 등록: {} ({}://{}:{})", info.id, info.scheme, info.host, info.port)
    }

    fun evictCluster(clusterId: String) {
        clientCache.remove(clusterId)?.let {
            runCatching { it.restClient.close() }
                .onFailure { e -> logger.warn("클러스터 클라이언트 종료 실패: $clusterId", e) }
        }
        logger.info("ES 클러스터 제거: {}", clusterId)
    }

    fun registeredClusterIds(): Set<String> = clientCache.keys.toSet()

    @PreDestroy
    fun closeAll() {
        clientCache.values.forEach { runCatching { it.restClient.close() } }
        clientCache.clear()
        logger.info("모든 ES 클러스터 클라이언트 종료 완료")
    }

    private fun buildCachedClient(info: ClusterConnectionInfo): CachedClusterClient {
        val host = HttpHost.create("${info.scheme}://${info.host}:${info.port}")
        val defaultHeaders = buildAuthHeaders(info)

        val restClient =
            Rest5Client
                .builder(host)
                .setDefaultHeaders(defaultHeaders)
                .build()

        val transport = Rest5ClientTransport(restClient, jsonpMapper)
        val esClient = ElasticsearchClient(transport)

        return CachedClusterClient(restClient, esClient)
    }

    private fun buildAuthHeaders(info: ClusterConnectionInfo): Array<Header> =
        when {
            !info.apiKey.isNullOrBlank() -> {
                arrayOf(BasicHeader("Authorization", "ApiKey ${info.apiKey}"))
            }
            !info.username.isNullOrBlank() && !info.password.isNullOrBlank() -> {
                val credentials = Base64.getEncoder().encodeToString("${info.username}:${info.password}".toByteArray())
                arrayOf(BasicHeader("Authorization", "Basic $credentials"))
            }
            else -> emptyArray()
        }

    private data class CachedClusterClient(
        val restClient: Rest5Client,
        val esClient: ElasticsearchClient,
    )

    data class ClusterConnectionInfo(
        val id: String,
        val scheme: String,
        val host: String,
        val port: Int,
        val username: String? = null,
        val password: String? = null,
        val apiKey: String? = null,
    )
}

package com.cowave.search.dictionary.controller

import com.cowave.search.dictionary.dto.AllTypesCountResponse
import com.cowave.search.dictionary.dto.AllTypesLastModifiedResponse
import com.cowave.search.dictionary.dto.CompileResult
import com.cowave.search.dictionary.dto.CreateDictionaryRequest
import com.cowave.search.dictionary.dto.CursorPagedResponse
import com.cowave.search.dictionary.dto.DictApplyHistory
import com.cowave.search.dictionary.dto.DictionarySetting
import com.cowave.search.dictionary.dto.SearchColumn
import com.cowave.search.dictionary.dto.SortType
import com.cowave.search.dictionary.dto.TypeCountResponse
import com.cowave.search.dictionary.dto.TypeLastModifiedResponse
import com.cowave.search.dictionary.dto.UpdateDictionaryRequest
import com.cowave.search.dictionary.model.Dictionary
import com.cowave.search.dictionary.model.Type
import com.cowave.search.dictionary.service.DictionaryService
import org.springframework.http.HttpHeaders
import org.springframework.http.HttpStatus
import org.springframework.http.MediaType
import org.springframework.http.ResponseEntity
import org.springframework.web.bind.annotation.DeleteMapping
import org.springframework.web.bind.annotation.GetMapping
import org.springframework.web.bind.annotation.PathVariable
import org.springframework.web.bind.annotation.PostMapping
import org.springframework.web.bind.annotation.PutMapping
import org.springframework.web.bind.annotation.RequestBody
import org.springframework.web.bind.annotation.RequestHeader
import org.springframework.web.bind.annotation.RequestMapping
import org.springframework.web.bind.annotation.RequestParam
import org.springframework.web.bind.annotation.ResponseStatus
import org.springframework.web.bind.annotation.RestController
import org.springframework.web.multipart.MultipartFile

@RestController
@RequestMapping("/dictionaries")
class DictionaryController(
    private val dictionaryService: DictionaryService,
) {
    /**
     * 사전 조회/검색 통합 API
     * - word가 없으면 전체 조회
     * - word가 있으면 검색 (searchColumn에 따라 대상 필드 결정)
     */
    @GetMapping("/{type}")
    fun getDictionary(
        @RequestHeader("cluster-id") clusterId: String,
        @PathVariable type: Type,
        @RequestParam(defaultValue = "20") size: Int,
        @RequestParam(required = false) cursor: String?,
        @RequestParam(defaultValue = "UPDATED") sort: SortType,
        @RequestParam(defaultValue = "ALL") searchColumn: SearchColumn,
        @RequestParam(required = false) word: String?,
        @RequestParam(defaultValue = "false") isMatch: Boolean,
    ): CursorPagedResponse<Dictionary> =
        dictionaryService.search(
            clusterId = clusterId,
            type = type,
            size = size,
            searchColumn = searchColumn,
            word = word,
            isMatch = isMatch,
            cursor = cursor,
            sortType = sort,
        )

    @GetMapping("/{type}/count")
    fun countByType(
        @RequestHeader("cluster-id") clusterId: String,
        @PathVariable type: Type,
    ): TypeCountResponse = TypeCountResponse(type, dictionaryService.countByType(clusterId, type))

    @GetMapping("/{type}/last-modified")
    fun getLastModifiedByType(
        @RequestHeader("cluster-id") clusterId: String,
        @PathVariable type: Type,
    ): TypeLastModifiedResponse = dictionaryService.getLastModifiedByType(clusterId, type)

    @GetMapping("/last-modified")
    fun getAllTypesLastModified(
        @RequestHeader("cluster-id") clusterId: String,
    ): AllTypesLastModifiedResponse = dictionaryService.getAllTypesLastModified(clusterId)

    @GetMapping("/count")
    fun getAllTypesCounts(
        @RequestHeader("cluster-id") clusterId: String,
    ): AllTypesCountResponse = dictionaryService.getAllTypesCounts(clusterId)

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    fun create(
        @RequestHeader("cluster-id") clusterId: String,
        @RequestBody request: CreateDictionaryRequest,
    ) {
        dictionaryService.create(clusterId, request.keyword, request.type, request.value)
    }

    @PutMapping("/{id}")
    fun update(
        @RequestHeader("cluster-id") clusterId: String,
        @PathVariable id: String,
        @RequestBody request: UpdateDictionaryRequest,
    ) {
        dictionaryService.update(clusterId, id, request.keyword, request.type, request.value)
    }

    @DeleteMapping("/{id}")
    @ResponseStatus(HttpStatus.NO_CONTENT)
    fun delete(
        @RequestHeader("cluster-id") clusterId: String,
        @PathVariable id: String,
    ) {
        dictionaryService.delete(clusterId, id)
    }

    @PostMapping("/compile/{type}")
    fun compile(
        @RequestHeader("cluster-id") clusterId: String,
        @PathVariable type: Type,
    ): CompileResult = dictionaryService.compile(clusterId, type)

    @PostMapping("/compile")
    fun compileAll(
        @RequestHeader("cluster-id") clusterId: String,
    ): List<CompileResult> = dictionaryService.compileAll(clusterId)

    // ── ROADMAP 2-2 추가 엔드포인트 ─────────────────────────────────────

    @PostMapping("/{type}/fileUpload")
    fun fileUpload(
        @RequestHeader("cluster-id") clusterId: String,
        @PathVariable type: Type,
        @RequestParam("file") file: MultipartFile,
    ): ResponseEntity<Map<String, Any>> {
        val count = dictionaryService.fileUpload(clusterId, type, file)
        return ResponseEntity.ok(mapOf("count" to count, "result" to "OK"))
    }

    @GetMapping("/{type}/download")
    fun download(
        @RequestHeader("cluster-id") clusterId: String,
        @PathVariable type: Type,
    ): ResponseEntity<ByteArray> {
        val content = dictionaryService.downloadAll(clusterId, type)
        val headers =
            HttpHeaders().apply {
                contentType = MediaType.TEXT_PLAIN
                setContentDispositionFormData("attachment", "${type.name.lowercase()}.txt")
            }
        return ResponseEntity.ok().headers(headers).body(content.toByteArray(Charsets.UTF_8))
    }

    @DeleteMapping("/resetDict/{type}")
    @ResponseStatus(HttpStatus.NO_CONTENT)
    fun resetDict(
        @RequestHeader("cluster-id") clusterId: String,
        @PathVariable type: Type,
    ) {
        dictionaryService.resetDict(clusterId, type)
    }

    @GetMapping("/settings")
    fun getSettings(
        @RequestHeader("cluster-id") clusterId: String,
    ): List<DictionarySetting> = dictionaryService.getSettings(clusterId)

    @GetMapping("/applyHistory")
    fun getApplyHistory(
        @RequestHeader("cluster-id") clusterId: String,
        @RequestParam(defaultValue = "20") size: Int,
    ): List<DictApplyHistory> = dictionaryService.getApplyHistory(clusterId, size)
}

fun compile(
    clusterId: String,
    type: Type,
): CompileResult {
    val result = compileWithoutReload(clusterId, type)
    reloadDictionary(clusterId)
    return result
}

fun compileAll(clusterId: String): List<CompileResult> {
    val results: List<CompileResult> = Type.entries.map { compileWithoutReload(clusterId, it) }
    reloadDictionary(clusterId)
    return results
}

private fun compileWithoutReload(
    clusterId: String,
    type: Type,
): CompileResult {
    val dictionaries = dictionaryRepository.findAllByType(clusterId, type)
    val pairs = dictionaries.map { it.keyword to it.value }
    val outputFile = dictionaryBinaryCompile.compileToConfiguredPath(pairs, type)

    return CompileResult(
        type = type,
        count = dictionaries.size,
        filePath = outputFile.absolutePath,
        fileSize = outputFile.length(),
    )
}

private fun reloadDictionary(clusterId: String) {
    logger.info("Reloading dictionary in Elasticsearch cluster: {}", clusterId)
    val restClient = clientFactory.getLowLevelClient(clusterId)
    val request = Request("POST", "/_analysis-product-name/reload-dict")
    val response = restClient.performRequest(request)
    val statusCode = response.statusCode
    if (statusCode !in 200..299) {
        throw RuntimeException("Failed to reload dictionary: HTTP $statusCode")
    }
    logger.info("Dictionary reload completed successfully for cluster: {}", clusterId)
}

package com.cowave.search.utils

import com.cowave.search.config.DictionaryConfig
import com.cowave.search.dictionary.model.Type
import org.springframework.stereotype.Component
import java.io.File

/**
 * 사전 바이너리 컴파일러
 * ES 인덱스에서 읽은 사전 데이터를 바이너리 파일로 컴파일
 *
 * 기존 Java analysis-product의 사전 바이너리 형식과 100% 호환
 */
@Component
class DictionaryBinaryCompile(
    private val dictionaryConfig: DictionaryConfig,
) {
    /**
     * 설정된 출력 경로 반환
     */
    fun getOutputPath(): String = dictionaryConfig.outputPath

    /**
     * Type에 따른 출력 파일 경로 반환 (설정된 경로 사용)
     */
    fun getOutputFile(type: Type): File = File(dictionaryConfig.outputPath, getOutputFileName(type))

    /**
     * ES에서 조회한 Dictionary 목록을 설정된 경로에 컴파일
     * @param dictionaries ES에서 조회한 사전 데이터 (keyword, value 쌍)
     * @param type 사전 타입
     * @param ignoreCase 대소문자 무시 여부
     * @return 생성된 파일
     */
    fun compileToConfiguredPath(
        dictionaries: List<Pair<String?, String?>>,
        type: Type,
        ignoreCase: Boolean = true,
    ): File {
        val outputFile = getOutputFile(type)
        compileFromDictionaries(dictionaries, type, outputFile, ignoreCase)
        return outputFile
    }

    /**
     * 설정된 경로에서 사전 파일 로드
     * @param type 사전 타입
     * @param ignoreCase 대소문자 무시 여부
     * @return 로드된 사전 데이터
     */
    fun loadFromConfiguredPath(
        type: Type,
        ignoreCase: Boolean = true,
    ): Any = load(type, getOutputFile(type), ignoreCase)

    /**
     * 기존 Type enum과 매핑하여 사전 컴파일
     * SET 타입: STOP, UNIT, USER, ENGLISH
     * SYNONYM 타입: SYNONYM, UNIT_SYNONYM
     * SPACE 타입: SPACE
     * COMPOUND 타입: COMPOUND
     */
    fun compile(
        type: Type,
        data: Any,
        outputFile: File,
    ) {
        outputFile.parentFile?.mkdirs()

        when (type) {
            Type.STOP, Type.UNIT, Type.USER, Type.ENGLISH -> {
                SetDictionarySerializer.writeTo(data as SetDictionaryData, outputFile)
            }

            Type.SYNONYM, Type.UNIT_SYNONYM -> {
                SynonymDictionarySerializer.writeTo(data as SynonymDictionaryData, outputFile)
            }

            Type.SPACE -> {
                SpaceDictionarySerializer.writeTo(data as SpaceDictionaryData, outputFile)
            }

            Type.COMPOUND -> {
                CompoundDictionarySerializer.writeTo(data as CompoundDictionaryData, outputFile)
            }
        }
    }

    /**
     * 바이너리 사전 파일을 읽어서 데이터 객체로 반환
     */
    fun load(
        type: Type,
        inputFile: File,
        ignoreCase: Boolean = true,
    ): Any =
        when (type) {
            Type.STOP, Type.UNIT, Type.USER, Type.ENGLISH -> {
                SetDictionarySerializer.readFrom(inputFile, ignoreCase)
            }

            Type.SYNONYM, Type.UNIT_SYNONYM -> {
                SynonymDictionarySerializer.readFrom(inputFile, ignoreCase)
            }

            Type.SPACE -> {
                SpaceDictionarySerializer.readFrom(inputFile, ignoreCase)
            }

            Type.COMPOUND -> {
                CompoundDictionarySerializer.readFrom(inputFile, ignoreCase)
            }
        }

    /**
     * ES에서 조회한 Dictionary 목록을 타입별로 컴파일
     * @param dictionaries ES에서 조회한 사전 데이터 (keyword, value 쌍)
     * @param type 사전 타입
     * @param outputFile 출력 파일
     * @param ignoreCase 대소문자 무시 여부
     */
    fun compileFromDictionaries(
        dictionaries: List<Pair<String?, String?>>,
        type: Type,
        outputFile: File,
        ignoreCase: Boolean = true,
    ) {
        val data =
            when (type) {
                Type.STOP, Type.UNIT, Type.USER, Type.ENGLISH -> {
                    // SET 타입: keyword만 사용
                    val words =
                        dictionaries
                            .mapNotNull { it.first?.trim() }
                            .filter { it.isNotEmpty() }
                            .toSet()
                    SetDictionaryData(words, ignoreCase)
                }

                Type.SYNONYM, Type.UNIT_SYNONYM -> {
                    // SYNONYM 타입: keyword -> value 매핑
                    createSynonymFromPairs(dictionaries, ignoreCase)
                }

                Type.SPACE -> {
                    // SPACE 타입: keyword -> value (공백 분리)
                    createSpaceFromPairs(dictionaries, ignoreCase)
                }

                Type.COMPOUND -> {
                    // COMPOUND 타입: keyword -> value (복합어 분해)
                    createCompoundFromPairs(dictionaries, ignoreCase)
                }
            }
        compile(type, data, outputFile)
    }

    /**
     * SYNONYM 타입 사전 생성 (keyword, value 쌍으로부터)
     */
    private fun createSynonymFromPairs(
        pairs: List<Pair<String?, String?>>,
        ignoreCase: Boolean,
    ): SynonymDictionaryData {
        val synonymMap = mutableMapOf<String, MutableList<String>>()
        val wordSet = mutableSetOf<String>()

        for ((keyword, value) in pairs) {
            if (value.isNullOrBlank()) continue

            val synonyms = value.split(",").map { it.trim() }.filter { it.isNotEmpty() }

            if (!keyword.isNullOrBlank()) {
                // 단방향: keyword -> synonyms
                val key = keyword.trim()
                synonymMap.getOrPut(key) { mutableListOf() }.addAll(synonyms)
                wordSet.add(key)
                wordSet.addAll(synonyms)
            } else {
                // 양방향: 모든 단어가 서로 동의어
                for (word in synonyms) {
                    val others = synonyms.filter { it != word }
                    synonymMap.getOrPut(word) { mutableListOf() }.addAll(others)
                }
                wordSet.addAll(synonyms)
            }
        }

        return SynonymDictionaryData(synonymMap, wordSet, ignoreCase)
    }

    /**
     * SPACE 타입 사전 생성 (keyword, value 쌍으로부터)
     *
     * Java 원본(SpaceDictionary.java:60-73)과 100% 동일한 로직:
     * 1. values[0]에서 공백을 제거하여 key 생성
     * 2. values[0]을 공백으로 split하여 value 배열 생성 (빈 문자열 포함!)
     * 3. wordSet에는 key와 비-ASCII 단어만 추가
     *
     * IMPORTANT: Java는 split("\\s")를 사용하여 연속 공백 시 빈 문자열이 생성됨
     * 예: "클린  스트라이프" → ["클린", "", "스트라이프"]
     * 빈 문자열은 RuleOne.java:45에서 setDisableEntry() 트리거하여 분석 동작에 영향
     * 바이너리 호환성을 위해 빈 문자열을 그대로 유지해야 함
     */
    private fun createSpaceFromPairs(
        pairs: List<Pair<String?, String?>>,
        ignoreCase: Boolean,
    ): SpaceDictionaryData {
        val spaceMap = mutableMapOf<String, List<String>>()
        val wordSet = mutableSetOf<String>()
        // Java: Pattern.compile("^[\\x00-\\x7F]*$") - ASCII 패턴
        val asciiPattern = Regex("^[\\x00-\\x7F]*$")

        for ((keyword, value) in pairs) {
            // Java: values[0]만 사용 - ES 데이터에서는 keyword 또는 value 중 하나 사용
            val sourceText = keyword?.takeIf { it.isNotBlank() } ?: value
            if (sourceText.isNullOrBlank()) continue

            // SPACE 타입 분리어 사전 때문에 아래와 같이 필요
            // - "\\s+"를 사용하면 연속 공백이 하나로 병합되어 리스트 길이가 달라짐
            // - 예: "가 나  다".split("\\s") → ["가", "나", "", "다"] (4개)
            //       "가 나  다".split("\\s+") → ["가", "나", "다"] (3개)
            // - 바이너리 포맷이 리스트 길이를 저장하므로 Java와 동일해야 함
            val key = sourceText.replace(Regex("\\s"), "")
            if (key.isEmpty()) continue

            val splitWords =
                sourceText
                    .split(Regex("\\s"))
                    .map { it.trim() }
            // 빈 문자열 유지: .filter { it.isNotEmpty() } 제거

            spaceMap[key] = splitWords
            wordSet.add(key) // 공백 제거된 키 추가

            // Java: ASCII 패턴 매치 안되는 것만 추가 (비-ASCII 단어만)
            // 빈 문자열은 ASCII로 매치되므로 wordSet에 추가되지 않음
            for (word in splitWords) {
                if (word.isNotEmpty() && !asciiPattern.matches(word)) {
                    wordSet.add(word)
                }
            }
        }

        return SpaceDictionaryData(spaceMap, wordSet, ignoreCase)
    }

    /**
     * COMPOUND 타입 사전 생성 (keyword, value 쌍으로부터)
     */
    private fun createCompoundFromPairs(
        pairs: List<Pair<String?, String?>>,
        ignoreCase: Boolean,
    ): CompoundDictionaryData {
        val compoundMap = mutableMapOf<String, List<String>>()
        val mainWordSet = mutableSetOf<String>()
        val wordSet = mutableSetOf<String>()

        for ((keyword, value) in pairs) {
            if (keyword.isNullOrBlank() || value.isNullOrBlank()) continue

            val key = keyword.trim()
            val parts =
                value
                    .split(",")
                    .map { it.trim() }
                    .filter { it.isNotEmpty() }

            compoundMap[key] = parts
            mainWordSet.add(key)
            wordSet.addAll(parts)
        }

        return CompoundDictionaryData(compoundMap, mainWordSet, wordSet, ignoreCase)
    }

    /**
     * Type에 따른 출력 파일명 생성
     */
    fun getOutputFileName(type: Type): String =
        when (type) {
            Type.STOP -> "stop.dict"
            Type.UNIT -> "unit.dict"
            Type.USER -> "user.dict"
            Type.ENGLISH -> "english.dict"
            Type.SYNONYM -> "synonym.dict"
            Type.UNIT_SYNONYM -> "unit_synonym.dict"
            Type.SPACE -> "space.dict"
            Type.COMPOUND -> "compound.dict"
        }
}

